"""Scoped Day 1 editorial sources. Does not alter paid product behavior."""
from pathlib import Path
import re,json,html
from PIL import Image
R=Path(__file__).resolve().parents[3]
D=Path(__file__).resolve().parent
E=html.escape
articles=[]
def p(s):return '<p>'+s+'</p>'
def h(s):return '<h2>'+s+'</h2>'
def table(c,headers,rows):
 return '<div class="table-wrap"><table><caption>'+c+'</caption><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def add(slug,title,desc,alt,img,sections,sources,related):
 body=p(desc)+p('<strong>Example basis:</strong> All businesses, amounts and outcomes below are fictional planning examples in USD, prepared November 4, 2026. They are not industry benchmarks or customer results.')
 toc=[]
 for n,(heading,content) in enumerate(sections,1):
  toc.append(f'<li><a href="#section-{n}">{E(heading)}</a></li>')
  body+=f'<h2 id="section-{n}">{E(heading)}</h2>'+content
 body='<nav class="toc" aria-label="On this page"><strong>On this page</strong><ol>'+''.join(toc)+'</ol></nav>'+body
 body+=h('Sources and method')+p('The worked calculations are original illustrations. These primary publisher resources explain relevant report or planning structures; platform definitions and capabilities can differ from this manual example.')+'<ul>'+''.join(f'<li><a href="{u}">{E(t)}</a></li>' for t,u in sources)+'</ul>'
 articles.append(dict(slug=slug,title=title,desc=desc,alt=alt,img=img,body=body,related=related,sources=sources))
add('store-performance-dashboard','Store Performance Dashboard: Sales, Margin & Stock Example','Build a store performance dashboard that reconciles orders, refunds, gross margin and available stock. Use a worked example and a weekly review template.','Shop owner reviewing stock and sales records in a clothing boutique','exec-3f4b5f12-f8c9-4ff4-8885-15586c253884.png',[
('What a store performance dashboard should show',p('A store performance dashboard brings sales, margin, stock and exceptions into one review. Start with a closed reporting period and show the source and cutoff beside every number. Revenue alone cannot tell you whether a shop can afford its next purchase or fulfill its next order.')+p('Use four groups: orders and net sales; product cost and gross margin; sellable versus reserved inventory; and decisions with an owner and date. A payment balance belongs in a separate cash view because tax, settlement delays and earlier sales can change the relationship between sales and money received.')),
('Worked sales and margin dashboard',p('In this closed fictional cohort, 110 orders were placed, 10 cancelled before fulfillment, and 100 fulfilled. The fulfilled orders originally contained $6,000 of merchandise before $300 of discounts. Later refunds were $570. Shipping and tax are excluded throughout.')+table('Closed-cohort merchandise results',['Measure','Calculation','Result'],[['Net sales','6,000 − 300 − 570','$5,130'],['Net product cost','3,000 dispatched cost − 270 resalable returns','$2,730'],['Gross profit','5,130 − 2,730','$2,400'],['Gross margin','2,400 ÷ 5,130 × 100','46.78%'],['Net sales per fulfilled order','5,130 ÷ 100','$51.30'],['Orders with a return','10 ÷ 100 fulfilled','10%']])+p('Here the $270 cost reversal belongs only to returned stock released for resale. A damaged returned item remains a cost in this simplified management view. Do not reverse its cost merely because a refund was issued. Formal accounting treatment depends on the underlying records.')+p('The $51.30 average uses all 100 fulfilled orders, including orders later refunded. The pre-refund discounted average is $5,700 ÷ 100 = $57. Both can be useful, but calling both “average order value” without a definition creates a false trend. Record the numerator and denominator beside the card.')),
('Reconcile units before calling stock available',table('Illustrative physical-stock bridge',['Movement','Units','Meaning'],[['Opening sellable stock','200','Released for sale'],['Receipts','+80','Received and checked'],['Shipped','−120','Physical units dispatched'],['Resalable returns released','+9','Checked and returned to sellable stock'],['Other damage write-offs','−2','Separate from returned goods'],['Closing sellable stock','167','200 + 80 − 120 + 9 − 2'],['Reserved','40','Already committed'],['Available to promise','127','167 − 40']])+p('For this example each of the ten returned orders contains one returned unit: nine are resalable and one is quarantined. That quarantined item is not in the 167 sellable units. Net units sold are 120 − 10 = 110; they are a different measure from 127 units available to promise. In a real store, returns can contain several units and an order count cannot substitute for a unit count.')+p('Check availability by SKU, size and location. A healthy total may conceal a sold-out medium and slow-moving large. Use the <a href="/journal/reorder-point-small-business/">reorder-point guide</a> to combine demand and supplier lead time rather than automatically replacing every sale.')),
('Copy this weekly review structure',table('Manual dashboard specification',['Field','Record','Decision'],[['Period and basis','Week ending, timezone, closed or provisional','Compare like periods'],['Metric definition','Net sales, cancellations, refund timing','Avoid mismatched denominators'],['Evidence','Order export, cost record, stock count','Investigate missing costs'],['Exception','SKU, issue, units affected','Choose a concrete action'],['Owner and date','Named reviewer, next check','Close the loop']])+p('At the same time each week, reconcile orders to the sales export, returned units to their condition record, and stock to a count or verified inventory ledger. Preserve the earlier export rather than silently replacing it when a late refund arrives. For an open period, label the report provisional and disclose whether refunds are attributed to their original order cohort or the date processed.')+p('A useful action is “check medium-size availability and supplier lead time before Friday’s reorder,” not “increase sales.” If sales rise while gross margin falls, inspect discounting, product mix and missing landed costs before increasing advertising.')),
('Common dashboard mistakes and practical answers',p('<strong>Can sales and refunds use different dates?</strong> Yes, but label the method. A calendar-period refund total and a closed-order-cohort return rate answer different questions. Do not compare them as if they used the same base.')+p('<strong>Is gross profit money available to spend?</strong> No. Operating expenses, tax, supplier payments and settlement timing remain. Use the <a href="/journal/financial-dashboard-example/">financial dashboard bridge</a> to separate profit and cash.')+p('<strong>Does this guide connect to my POS?</strong> No. It is a manual dashboard specification. Check your platform’s definitions and export behavior, and the exact features on the <a href="/planners/boutique-business-planner/">Boutique Business Planner page</a>, before choosing a working system.'))
],[('Shopify: store performance dashboard','https://www.shopify.com/blog/store-performance-dashboard'),('Shopify Help: overview dashboard','https://help.shopify.com/en/manual/reports-and-analytics/shopify-reports/overview-dashboard/using-the-overview-dashboard'),('Shopify Help: profit reports','https://help.shopify.com/en/manual/reports-and-analytics/shopify-reports/report-types/default-reports/profit-reports')],'/planners/boutique-business-planner/')
add('project-management-dashboard','Project Management Dashboard: Budget, Capacity & Delivery','Create a project management dashboard with weighted progress, forecast cost, role capacity and delivery dates. Includes a reconciled project example.','Project coordinator reviewing a physical task board with color-coded cards','exec-ffe506c8-9f5f-4157-bbd3-83db3259bb11.png',[
('Choose the decisions before the charts',p('A project management dashboard should tell a reviewer what has been accepted, whether the delivery date is still credible, what completion is likely to cost, and which decision is blocking work. A task count alone is too weak: finishing two small tasks does not mean half a project is delivered.')+p('For a single project, use accepted deliverables, baseline versus forecast dates, actual plus remaining cost, capacity by role, and an exception list. A portfolio dashboard adds a separate comparison across projects. Keep the scope and audience explicit so an executive summary does not expose unnecessary client or staff details.')),
('Calculate progress from accepted work',table('Illustrative weighted deliverables, as of November 4, 2026',['Deliverable','Weight','Accepted completion','Earned points'],[['Discovery','10','100%','10'],['Design','15','100%','15'],['Build','55','40%','22'],['Launch','20','0%','0'],['Total','100','Weighted progress','47']])+p('Weighted progress is the sum of weight × accepted completion: 10 + 15 + 22 + 0 = 47%. The weights describe this fictional scope, not a universal standard. Define how a partial build earns acceptance; a developer’s estimate of effort spent is not equivalent to a client accepting functionality.')+p('Two of four deliverables are complete, so the raw count is 50%. That is a different measure. If the baseline expected 60 weighted points by this cutoff, actual progress trails by 13 percentage points. Avoid reporting “13% late”: relative percentages, schedule days and percentage points are different quantities.')),
('Show forecast cost rather than spend alone',table('Illustrative delivery and cost cards',['Card','Inputs','Result'],[['Approved budget','$10,000','Baseline held unchanged'],['Actual cost','$5,600','56% of budget spent'],['Remaining estimate','$5,900','Based on unfinished scope'],['Forecast total','5,600 + 5,900','$11,500'],['Forecast variance','11,500 − 10,000','$1,500 over budget'],['Launch date','November 20 baseline; November 25 forecast','5 calendar days later']])+p('Spending 56% of the budget does not establish 56% completion; accepted progress is 47%. Do not calculate remaining cost as budget minus spend when the delivery estimate says otherwise. A $5,900 remaining estimate requires a forecast of $11,500 even when the approved budget is still $10,000.')+p('Show scope changes with their approval date and value. Preserve the original baseline so an approved change is visible rather than rewriting history to make every variance disappear. The date comparison above uses calendar days, not working days or a holiday calendar.')),
('Capacity must match the role',table('Next-period role capacity',['Role','Available hours','Booked hours','Gap'],[['Designer','12','10','2 spare'],['Developer','22','30','8 short'],['Total','34','40','6 net short']])+p('The net six-hour shortfall understates the delivery problem if the designer cannot do the developer’s work. The developer is eight hours short. Resolve that role constraint through a scoped reduction, a qualified reassignment or a revised date; do not treat two spare design hours as interchangeable development capacity.')+p('Availability should already exclude approved leave, recurring support and other commitments. Use estimates for the same time window as the capacity total. A monthly availability number cannot validate a deadline next Friday. For multi-client work, compare the <a href="/planners/agency-client-profitability-capacity-os/">agency profitability and capacity planner</a> against your actual process.')),
('Copyable dashboard fields and review agenda',p('For each deliverable record: ID, owner, baseline date, forecast date, weight, acceptance criterion, evidence link, accepted completion, remaining hours, cost rate and last-updated date. Record a blocker’s decision owner and due date separately. Keep detailed notes in the project record and show only exceptions on the dashboard.')+p('At review, first check stale data and missing acceptance evidence. Then discuss the critical blocker, the role shortfall and the forecast budget variance. End with decisions and dates. In this example an approval due November 6 needs an owner; marking the card amber without assigning a decision does not resolve the delay.')+p('<strong>Can I use a spreadsheet?</strong> Yes, if formulas, permissions and version history fit the team. This guide describes a manual review structure, not automatic Asana or other platform integration. <strong>Should every project use these weights?</strong> No. Agree them before measuring progress and retain a dated record when the scope changes.'))
],[('Asana Help: project dashboards','https://help.asana.com/s/article/how-to-create-project-dashboards'),('Smartsheet: project portfolio dashboards','https://www.smartsheet.com/content/project-portfolio-dashboards')],'/planners/agency-client-profitability-capacity-os/')
add('fashion-line-business-plan','Fashion Line Business Plan: Collection Costs, Sizes & Launch Cash','Write a fashion line business plan with a small collection, size-level stock, returns, launch costs and cash. Includes a filled financial example.','Fashion designer comparing fabric swatches beside garment sketches and a teal jacket','exec-3344b6a6-cf35-481e-911b-9f034ae2378f.png',[
('Define a collection you can actually produce',p('A fashion line business plan connects a customer hypothesis to design, samples, production quantities, fit, selling costs and cash. For an own-label collection, a generic retail plan is incomplete: patterns, samples, size distribution and minimum orders can commit money before the first customer buys.')+p('This fictional launch offers two coordinated styles: an overshirt and trousers. Its hypothesis is that buyers want a small mix-and-match workwear range. That is an assumption to test with interviews, fitting feedback and paid orders, not evidence of demand. The plan names a launch owner, a supplier quote date and a decision date before expanding the range.')),
('Price the opening collection and setup',table('Illustrative opening commitment',['Line','Calculation','Cash out'],[['Overshirts','80 × $24 landed cost','$1,920'],['Trousers','60 × $20 landed cost','$1,200'],['Opening stock','140 units','$3,120'],['Samples and patterns','Quoted assumption','$600'],['Photography','One launch shoot','$240'],['Storefront setup','One-off setup','$140'],['Total opening commitment','3,120 + 980','$4,100']])+p('Opening cash of $6,000 leaves $1,900 after those commitments, before customer receipts and later selling costs. Landed cost here includes the assumed cost of bringing a garment into stock; validate freight, duties, packaging and rejected pieces against actual supplier terms instead of copying the $24 or $20 example.')+p('Ask for minimum quantities by style, color and size, sample revision limits, delivery dates, payment milestones and a written quality-check process. A low unit quote can still require more cash if the minimum order is too large. Use the <a href="/journal/supplier-quote-comparison/">supplier quote comparison</a> to compare the same cost boundary.')),
('Model sales after returns, not just launch revenue',table('Illustrative first-month trading model',['Line','Calculation','Result'],[['Gross shipped merchandise','30 overshirts × $60 + 20 trousers × $50','$2,800'],['Refunds','3 overshirts × $60 + 2 trousers × $50','−$280'],['Net revenue','2,800 − 280','$2,520'],['Net cost of sold stock','27 × $24 + 18 × $20','$1,008'],['Gross profit','2,520 − 1,008','$1,512'],['Selling costs','Fees 90 + packing 100 + outbound 210 + returns 40 + ads 300','$740'],['Contribution before launch setup, tax and owner pay','1,512 − 740','$772']])+p('All five returned garments are assumed checked and resalable. Closing stock is 53 overshirts and 42 trousers: 95 units costing $2,112. Net unit sell-through is 45 ÷ 140 = 32.14%. Damaged or unsellable returns would change stock value and cost; do not use this example without adjusting that assumption.')+p('If all $980 of one-off launch setup were charged against this management period, the $772 contribution would become a $208 shortfall before tax and owner pay. That is an illustration of launch economics, not a claim about formal accounting treatment.')),
('Check sizes and cash independently',table('Overshirt size example',['Size','Opening','Shipped','Resalable returns','Closing'],[['S','20','5','1','16'],['M','30','18','1','13'],['L','30','7','1','24'],['Total','80','30','3','53']])+p('Medium sell-through is 17 ÷ 30 = 56.67%; small and large are each 20%. Reordering the original size ratio would ignore the evidence. Check fit complaints and the small sample size before treating one month as a permanent demand pattern.')+p('Assuming the full $2,520 of net customer receipts is collected in the month and the $740 selling costs are paid separately, closing cash is $6,000 − $4,100 + $2,520 − $740 = $3,680. Do not subtract the $1,008 cost of sold stock again: the opening inventory purchase is already in the $4,100 cash outflow. If your payment processor pays net of fees, reconcile the payout before deducting those fees a second time.')),
('Fill the plan and set 30, 60 and 90-day decisions',p('Copy these fields: target buyer and evidence; two-style offer; size range and fit notes; supplier quote and minimum order; samples and approvals; opening stock by variant; prices and return assumptions; fulfillment capacity; cash dates; marketing test; owner and review date. Attach the source for each estimate.')+p('By day 30 compare paid orders, retained units, fit feedback and contribution after selling costs. By day 60 compare size-level stock and supplier lead time before authorizing replenishment. By day 90 decide whether to repeat, revise or discontinue each style. Keep the original plan alongside actuals rather than replacing the forecast.')+p('The <a href="/planners/boutique-business-planner/">Boutique Business Planner</a> supports a broader boutique workflow; verify the current product format and modules before buying. This article supplies an original worked plan, not a ready-made manufacturing agreement. For a document front sheet, use the <a href="/tools/business-plan-cover-page/">free business plan cover page</a> after the business assumptions are written.'))
],[('Shopify: clothing line business plan','https://www.shopify.com/blog/clothing-line-business-plan'),('SBA: write your business plan','https://www.sba.gov/business-guide/plan-your-business/write-your-business-plan')],'/planners/boutique-business-planner/')
add('ecommerce-business-plan','Ecommerce Business Plan: Orders, Returns & Cash Example','Build an ecommerce business plan around conversion, fulfillment, returns, contribution and payment timing. Follow a reconciled 120-order example.','Ecommerce owner inspecting a returned garment beside separate stock and shipping containers','exec-907a6bc6-f061-4549-b294-e66d095e81b8.png',[
('Start with the offer and operating limits',p('An ecommerce business plan should explain what you sell, who buys it, why the offer is credible, and how orders turn into delivered goods and collected cash. A traffic target is only one input. Cancellation, returns, fulfillment cost and payment timing determine whether the plan can fund its next cycle.')+p('This fictional store sells one $50 product. It begins with a supplier quote, a 300-unit opening purchase and a monthly traffic hypothesis. Before launch, its owner must verify product demand, delivery promises, stock availability, customer support workload and the published return process. These are planning checks, not evidence that the product will sell.')),
('Keep each stage of the order funnel separate',table('Illustrative monthly order cohort',['Stage','Count','Interpretation'],[['Sessions','10,000','Consistent analytics definition'],['Carts','300','Not all carts become orders'],['Paid orders','120','1.20% of sessions'],['Pre-fulfillment cancellations','12','Fully refunded'],['Shipped orders','108','120 − 12'],['Full returns after shipment','6','All six units resalable'],['Retained orders','102','1.02% of sessions']])+p('The model assumes one item per order. If customers buy multiple units, replace the unit-cost model with item-level records. The paid conversion rate is 120 ÷ 10,000 = 1.20%; retained-order conversion is 102 ÷ 10,000 = 1.02%. They are not interchangeable. Also record whether returns belong to an original-order cohort or the processing period.')+p('Do not add orders claimed by multiple advertising platforms and call the sum unique sales. Use an agreed order-level attribution rule, deduplicate records and preserve a separate view of platform-reported claims.')),
('Calculate contribution after shipping and returns',table('Illustrative unit economics at cohort level',['Line','Calculation','Amount'],[['Booked merchandise','120 × $50','$6,000'],['Cancellation refunds','12 × $50','−$600'],['Return refunds','6 × $50','−$300'],['Net merchandise revenue','6,000 − 600 − 300','$5,100'],['Net product cost','108 × $20 − 6 × $20','$2,040'],['Fulfillment','108 × $5','$540'],['Payment fees','Assumed actual charges','$180'],['Return handling','6 × $4','$24'],['Advertising','Test budget','$900'],['Contribution','5,100 − 2,040 − 540 − 180 − 24 − 900','$1,416'],['Fixed site and support costs','100 + 300','$400'],['Modeled operating remainder','1,416 − 400','$1,016']])+p('The remainder excludes tax, owner pay and finance costs. Payment fees here are a fictional $180 total, not a provider rate. Cancellation handling, reshipping, chargebacks and damaged returns are zero in the example; add them when present. A contribution number is useful only when its cost boundary is clear.')+p('Check the fulfillment estimate against hours and provider quotes. If 108 shipments take eight minutes each, direct packing alone needs 864 minutes, or 14.4 hours, before support and returns. A revenue forecast does not create that capacity.')),
('Reconcile inventory and cash',p('The opening purchase costs 300 × $20 = $6,000. Closing inventory is 300 − 108 + 6 = 198 resalable units, costing $3,960. Net cost of sold stock is $2,040; it is an expense measure, while the $6,000 purchase is the cash commitment.')+table('Illustrative cash bridge',['Cash line','Amount'],[['Opening cash','$10,000'],['Opening stock purchase','−$6,000'],['Collected net customer receipts: 80% × $5,100','+$4,080'],['Fulfillment, fees, returns, ads and fixed costs','−$2,044'],['Closing cash','$6,036'],['Net customer amount still pending','$1,020']])+p('Here receipts are shown before separately paid fees. If actual processor payouts already deduct fees, refunds or reserves, reconcile them to gross movements rather than subtracting twice. The pending $1,020 is not in closing cash. A delayed payout changes cash timing even when retained-order revenue remains $5,100.')+p('Use a <a href="/journal/cash-flow-forecast-template-example/">dated 13-week cash forecast</a> to test supplier payment dates and delayed collections. Include existing liabilities and restricted amounts before deciding cash is available for another stock order.')),
('Copyable business-plan outline and decision rules',p('Write: executive summary; customer problem and evidence; product, price and supplier terms; sales channels and traffic assumptions; conversion and return definitions; stock and fulfillment capacity; cost model; receipt and payment dates; downside case; responsible owner and review dates. Use the <a href="/tools/business-plan-cover-page/">cover-page builder</a> only as the document front sheet, not as a substitute for these sections.')+p('In the first review, compare actual paid orders, cancellations, shipped units and returned condition. In the second, inspect contribution by product and channel using deduplicated orders. Before replenishment, confirm the supplier commitment fits the cash forecast if the pending $1,020 arrives late. Keep the original forecast to learn which assumption failed.')+p('<strong>Can one plan cover every store?</strong> No. Subscription, dropshipping, stocked goods and made-to-order models have different payment and inventory risks. This example is a stocked single-item model. <strong>Does positive contribution mean profitable growth?</strong> Not by itself; overhead, repeat buying, taxes and cash commitments still matter.'))
],[('Zoho Commerce: ecommerce business plan template','https://www.zoho.com/commerce/academy/ecommerce-business-plan-template.html'),('SBA: business plan structure','https://www.sba.gov/business-guide/plan-your-business/write-your-business-plan')],'/planners/boutique-business-planner/')
add('financial-dashboard-example','Financial Dashboard Example: Profit, Cash & Working Capital','Use a financial dashboard example to reconcile operating results, cash, receivables, payables and stock. Includes a transparent profit-to-cash bridge.','Calculator and financial planning papers beside a tablet with conceptual charts','exec-0209561d-1e97-4f02-8c6a-a1e0b86580b5.png',[
('What a useful financial dashboard answers',p('A financial dashboard should show whether operations are generating a surplus, whether cash can meet dated payments, and where money is tied up. Profit, cash and sales are different measures. A clear small-business view labels the period, currency, source, cost boundary and last reconciliation date.')+p('This example is a simplified management model, not formal financial statements or tax reporting. It excludes tax, interest, depreciation, financing and sales tax. It illustrates how the numbers connect; actual books need their own complete records and applicable accounting treatment.')),
('Read operating results beside cash',table('Illustrative month summary',['Measure','Calculation','Result'],[['Revenue','All on credit','$18,000'],['Consumed operating costs','Period cost boundary','$14,000'],['Modeled operating remainder','18,000 − 14,000','$4,000'],['Modeled margin','4,000 ÷ 18,000','22.22%'],['Opening cash','Verified starting balance','$12,000'],['Customer receipts','Collected in month','$15,000'],['Cash payments','All listed payments','$17,000'],['Closing cash','12,000 + 15,000 − 17,000','$10,000']])+p('The business shows a $4,000 modeled operating surplus while cash falls $2,000. Neither card is necessarily wrong. Some revenue is uncollected, purchases can increase inventory, and equipment or owner withdrawals can use cash outside this operating-cost boundary. Put the bridge beside the headline numbers so the reviewer can explain the difference.')),
('Reconcile receivables, payables and stock',table('Illustrative working-capital records',['Record','Bridge','Closing'],[['Customer receivables','5,000 opening + 18,000 credit revenue − 15,000 receipts','$8,000'],['Supplier payables','4,000 opening + 16,000 operating purchases − 14,000 operating payments','$6,000'],['Inventory increase','16,000 purchased − 14,000 consumed','$2,000 increase'],['Overdue receivables','3,000 overdue ÷ 8,000 total','37.5%']])+p('The $16,000 of purchases includes a $2,000 stock increase, so purchases and consumed costs differ. The model assumes no write-offs, credit notes or other balance movements. In a real report, show those adjustments explicitly. An overdue share of 37.5% says how much of this receivable balance is late; it is not a customer default probability.')+p('Age receivables by agreed due date and assign follow-up to an owner. For payables, use actual supplier due dates. A single net working-capital figure can hide the fact that a large payment is due tomorrow while a customer invoice is not collectible for several weeks.')),
('Follow the profit-to-cash bridge',table('Illustrative reconciliation of the $2,000 cash decline',['Movement','Cash effect'],[['Modeled operating remainder','+$4,000'],['Receivables increased from 5,000 to 8,000','−$3,000'],['Payables increased from 4,000 to 6,000','+$2,000'],['Inventory increased','−$2,000'],['Equipment purchase','−$2,000'],['Owner withdrawal','−$1,000'],['Net cash movement','−$2,000']])+p('Cash payments total $17,000: $14,000 operating payments, $2,000 equipment and $1,000 owner withdrawal. The equipment and withdrawal are separate cash uses in this model; treating both as ordinary operating costs would distort the comparison. Do not force a dashboard to reconcile by hiding unexplained differences in an “other” line.')+p('If the bridge does not match the bank movement, inspect dates, transfers, taxes, fees, loans, opening balances and missing transactions. Use the <a href="/journal/cash-flow-forecast-template-example/">cash forecast example</a> for future dates and the accounting records for actual transactions.')),
('Turn the dashboard into a payment decision',p('For the next 14 days, assume $4,500 of the closing payables is due, other commitments total $1,200, and confirmed expected customer receipts are $2,500. The listed-items forecast is $10,000 + $2,500 − $4,500 − $1,200 = $6,800. This is a conditional balance after listed commitments, not unrestricted spare cash. Verify omitted obligations, collection risk and restricted funds before authorizing spending.')+p('Copy these fields for each card: measure; period; formula; source export; reconciliation date; owner; exception; action date. Review stale sources before discussing trends. The <a href="/planners/cashflow-13-os/">CashFlow 13 planner</a> can support a rolling cash-planning workflow; this article does not connect to banks or replace bookkeeping.')+p('<strong>Should I put every financial metric on one screen?</strong> No. Keep the decision-critical summary readable and link the evidence. <strong>Is this a three-statement model?</strong> No. It is a deliberately bounded operating and cash example; a complete income statement, balance sheet and cash-flow statement requires additional classifications and records.'))
],[('Zoho Analytics: finance dashboard examples','https://www.zoho.com/analytics/dashboard-examples/finance.html'),('Geckoboard: cash flow dashboard example','https://www.geckoboard.com/dashboard-examples/finance/cash-flow-dashboard/')],'/planners/cashflow-13-os/')
add('client-dashboard-example','Client Dashboard Example: Outcomes, Progress & Decisions','Build a client dashboard that separates accepted work, deduplicated results, spend and decisions. Includes a fictional agency report and privacy checklist.','Agency lead discussing a conceptual report with a client at a desk','exec-2ab138ab-15e7-479c-844a-07c4e30a67d1.png',[
('Agree what the client needs to decide',p('A client dashboard is a shared summary of agreed outcomes, delivery status, results and decisions. Begin with the client’s objective and reporting window. An internal profitability worksheet and a client-facing report have different audiences; do not publish staff costs or other clients’ information merely because the fields are available.')+p('This fictional agency report covers October, with results through October 31 and a report prepared November 4, 2026. It uses aggregate counts and matched records, not real customer information. Late conversions are provisional and can change a later dated version.')),
('Separate deliverables from outcomes',table('Illustrative delivery status',['Status','Count','Definition'],[['Accepted','9','Client acceptance recorded'],['Awaiting approval','2','Submitted, not yet accepted'],['Revision requested','1','Further work required'],['Total agreed','12','Original scope'],['Acceptance rate','75%','9 ÷ 12']])+p('Do not report all 12 as complete because they have been submitted. Show who must approve the two waiting items and the next revision date for the remaining item. Keep the original scope and any approved changes separate so the client can understand why the denominator changed.')+p('Delivery is also different from business impact. Nine accepted assets do not prove that a campaign caused five new customers. Label observed outcomes and avoid turning a correlation into a causal claim.')),
('Use deduplicated results and cost definitions',table('Illustrative campaign measures',['Measure','Calculation','Result'],[['Advertising spend','Agreed media-only boundary','$600'],['Lead records','30 records − 6 duplicates','24 unique leads'],['Qualified leads','Agreed qualification rule','15'],['Observed new customers','Matched under documented rule','5'],['Cost per unique lead','600 ÷ 24','$25'],['Cost per qualified lead','600 ÷ 15','$40'],['Spend per observed new customer','600 ÷ 5','$120']])+p('If platform A claims 28 leads and platform B claims 14, their 42 reported claims are not automatically 42 unique people. In this example the deduplicated CRM total is 24. Keep source claims as separate diagnostic measures and use a documented identity and time-window rule for the shared total.')+p('A matched net revenue amount of $1,000 divided by $600 media spend is 1.67. Call that a revenue-to-media-spend ratio under the agreed matching rule, not ROI, profit or proof of incremental revenue. The $900 agency fee is excluded from the $600 spend card. Together those two outlays are $1,500, and product costs or other client expenses may still be missing.')),
('Copy a client-ready report layout',table('Copyable report sections',['Section','What to include'],[['Objective','One agreed business question and period'],['Delivery','Accepted, waiting and revision counts'],['Outcomes','Deduplicated counts with definitions'],['Spend','Included and excluded cost categories'],['Data note','Source cutoff, extraction date, provisional records'],['Decisions','Question, owner, deadline and next review']])+p('For the example, one decision is to approve or reject the two submitted assets by the next agreed review. Another is to inspect why nine of the 24 unique leads did not meet the qualification rule before increasing spend. Each action should identify the evidence needed, rather than saying “optimize performance.”')+p('Record a source register: analytics through October 31, platform export obtained November 2, and CRM extract obtained November 3. If their date windows differ, resolve the mismatch or label it. Do not use a November conversion to inflate an October result without explaining the attribution rule.')),
('Control sharing and maintain report versions',p('The client view should contain only approved aggregate fields and the records necessary for that client. Restrict raw identifiers, salaries, internal margin, unrelated projects and other clients’ information. Downloadable worksheets are not automatically secure client portals; permissions, authentication and retention need a separate working system.')+p('Before sharing, check the reporting dates, formulas, deduplication, expense boundary and approval status. Save a dated version and explain later adjustments. A missing source should appear as unavailable, not as zero. Never invent a customer testimonial or revenue result to fill an empty card.')+p('For internal multi-client capacity and profitability, compare the <a href="/planners/agency-client-profitability-capacity-os/">agency planning product</a>. For project-level date and budget forecasting, use the <a href="/journal/project-management-dashboard/">project dashboard example</a>. This article is a manual reporting design, not a claim that Nexaly supplies a live authenticated client portal.'))
],[('Assembly: client dashboard examples','https://assembly.com/blog/client-dashboard-examples'),('ClickUp: client dashboard guide','https://clickup.com/blog/client-dashboard/')],'/planners/agency-client-profitability-capacity-os/')
add('recruitment-company-business-plan','Recruitment Company Business Plan: Fees, Capacity & Cash','Write a recruitment company business plan with a niche, search capacity, fee assumptions, collection dates and a refund stress test. Includes a filled example.','Recruiter preparing anonymous candidate folders beside an interview desk','exec-6579769c-3293-4e8a-834b-b497f411e24c.png',[
('Choose a recruitment model and a focused market',p('A recruitment company business plan should define the hiring niche, buyer, service, fee event, delivery capacity and cash risk. Permanent placement and temporary staffing are different operating models. This example covers a founder-led permanent-placement agency; it does not model paying temporary workers or carrying a contractor payroll.')+p('The fictional agency serves a narrow set of operations roles for small employers. Its customer hypothesis needs evidence from buyer conversations, live hiring requirements and signed terms. The plan should explain why the agency can source and assess appropriate candidates without inventing a placement track record or candidate database.')),
('Set delivery capacity before accepting searches',table('Illustrative monthly founder capacity',['Item','Hours or count','Implication'],[['Working time','160 hours','Starting availability'],['Sales and administration','40 hours','Not delivery capacity'],['Search delivery time','120 hours','160 − 40'],['Requests received','6 searches','Not all accepted'],['Estimated effort','22 hours per active search','6 would need 132 hours'],['Accepted active searches','5 × 22 = 110 hours','10-hour delivery buffer'],['Queued request','1','Do not promise simultaneous delivery']])+p('Search hours should cover briefing, sourcing, screening, scheduling, feedback and candidate communication. The 22-hour estimate is hypothetical and not an industry standard. Record actual effort per search and revise acceptance limits when roles prove harder to fill.')+p('A request is not a placement and a placement is not collected cash. Keep searches opened, interviews, offers, starts, billings and collections as separate stages with consistent definitions. An active pipeline cannot be spent on software or owner withdrawals.')),
('Write the fee and payment assumptions explicitly',table('Illustrative first-month cash and billing model',['Line','Calculation','Amount'],[['Billings','2 modeled placements × $3,500 flat fee','$7,000'],['Customer receipts','1 invoice collected','$3,500'],['Outstanding invoice','1 unpaid invoice','$3,500'],['Operating payments','Software 300 + sourcing 500 + research contractor 1,500 + admin 200','$2,500'],['Owner withdrawal','Separate cash draw','$2,000'],['Opening cash','Starting balance','$6,000'],['Closing cash','6,000 + 3,500 − 2,500 − 2,000','$5,000']])+p('The $3,500 fee is a fictional flat amount, not a market rate, legal recommendation or promised result. Actual terms must specify the billing event, due date, replacement or refund conditions and accepted responsibilities. The modeled $7,000 is billings under the example assumption; revenue recognition can require a different accounting treatment.')+p('Billings less the modeled operating cost is $4,500 before tax, owner withdrawal and any reserve. That is not collected cash. The owner draw is shown as a separate cash use, not a wage expense in this simplified model. Validate the classification with the actual business structure and books.')),
('Stress-test delayed collections and guarantees',table('Illustrative next-month scenarios',['Scenario','Calculation','Closing cash'],[['No new placements; prior invoice collected','5,000 + 3,500 − 4,500','$4,000'],['No new placements; no collections','5,000 − 4,500','$500'],['No receipts; conditional full fee refund','5,000 − 4,500 − 3,500','−$3,000 gap']])+p('The $4,500 next-month outflow assumes the same $2,500 operating payments and $2,000 owner withdrawal. The refund scenario assumes a contract that requires a full $3,500 refund; it is not a universal recruitment guarantee. If the real agreement provides a replacement search instead, the pressure may be extra delivery work rather than the same immediate refund.')+p('Before accepting more commitments, map invoice due dates, client credit risk, potential refunds and owner withdrawals in a dated cash forecast. A placement target does not solve a timing gap. The <a href="/journal/cash-flow-forecast-template-example/">13-week cash example</a> shows how to move an expected receipt without counting it twice.')),
('Complete the plan and keep an evidence register',p('Copy these sections: niche and buyer; evidence of hiring demand; service boundaries; search intake and qualification; sourcing and screening process; fee and billing event; collection assumptions; active-search limit; delivery costs; cash scenarios; privacy and permissions; owner and review dates. A cover sheet can use the <a href="/tools/business-plan-cover-page/">free business plan cover page</a>, but it does not replace the plan.')+p('Keep candidate information in an appropriate controlled system, obtain the necessary permissions for sharing, and check applicable official requirements for the jurisdictions and recruitment model involved. This article does not determine licensing, employment, privacy or contract obligations. Avoid presenting a generic template as legal compliance.')+p('At the first monthly review compare hours per search, qualified client requests, agreed terms, starts, invoices and receipts. If search effort exceeds 22 hours, reduce the active limit or change scope before promising six searches. If collections lag, revise the cash scenario and withdrawal decision. For general owner priorities and follow-ups, inspect the current <a href="/planners/owneros-core/">OwnerOS Core product details</a>; no recruitment-specific ATS integration is implied.'))
],[('SBA: write your business plan','https://www.sba.gov/business-guide/plan-your-business/write-your-business-plan'),('RecruiterRoles: recruitment agency business plan','https://recruiterroles.com/blog/recruitment-agency-business-plan'),('Informi: starting a recruitment agency','https://informi.co.uk/starting-business/how-to-start-a-recruitment-agency')],'/planners/owneros-core/')


