 footer=template[template.index('<footer class="site">'):]
 manifest=[]
 for a in articles:
  slug=a['slug'];image='/images/journal/'+slug+'-20261104.webp';src=R.parent/'generated_images'/a['img'];dest=R/image.lstrip('/');dest.parent.mkdir(exist_ok=True,parents=True)
  with Image.open(src) as im: im.resize((1200,800)).save(dest,'WEBP',quality=83,method=6)
  url='https://nexalyplanner.com/journal/'+slug+'/'
  schema={'@context':'https://schema.org','@type':'BlogPosting','headline':a['title'],'description':a['desc'],'image':'https://nexalyplanner.com'+image,'mainEntityOfPage':url,'author':{'@type':'Organization','name':'NexalyPlanner','url':'https://nexalyplanner.com/about/'},'publisher':{'@type':'Organization','name':'NexalyPlanner'},'datePublished':'2026-11-04','dateModified':'2026-11-04','inLanguage':'en-US'}
  head=f'<!doctype html><html lang="en-US"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(a["title"])}</title><meta name="description" content="{E(a["desc"])}"><link rel="canonical" href="{url}"><meta property="og:image" content="https://nexalyplanner.com{image}"><meta name="twitter:image" content="https://nexalyplanner.com{image}"><meta property="og:image:alt" content="{E(a["alt"])}"><meta property="og:type" content="article"><meta property="article:published_time" content="2026-11-04"><meta property="article:modified_time" content="2026-11-04">{styles}<style>.reading h2{{scroll-margin-top:110px}}</style><link rel="stylesheet" href="/assets/css/style.css?v=7e6083e6f963"><script type="application/ld+json">{json.dumps(schema)}</script></head><body>'
  hero=f'<header class="article-hero"><div class="brand">NEXALYPLANNER JOURNAL</div><h1>{E(a["title"])}</h1><p class="metadata">By NexalyPlanner · Published November 4, 2026</p></header>'
  page=head+nav+hero+f'<main><p class="toplink"><a href="/journal/">Back to the Journal</a></p><article class="reading"><figure class="article-feature"><img src="{image}" width="1200" height="800" alt="{E(a["alt"])}" fetchpriority="high" decoding="async"><figcaption>AI-generated editorial illustration matched to this topic. Charts shown in the photograph are conceptual; use the worked tables below for exact figures.</figcaption></figure>'+a['body']+f'<aside class="related-guides"><h2>Continue planning</h2><p><a href="{a["related"]}">View the relevant planner and its exact features</a></p><p><a href="/journal/">Explore more practical planning guides</a></p></aside></article></main>'+footer
  path=R/'journal'/slug/'index.html';path.parent.mkdir(parents=True,exist_ok=True);path.write_text(page)
  manifest.append({k:a[k] for k in ['slug','title','alt','img','sources']}|{'asset':image,'word_count':len(re.sub('<[^>]+>',' ',a['body']).split())})
 (D/'articles.json').write_text(json.dumps(manifest,indent=2))
 print([(m['slug'],m['word_count']) for m in manifest])
